const reservation = $input.first().json.body.reservation;
const proposedTimeRaw = $input.first().json.body.proposed_time;
const proposedDateRaw = $input.first().json.body.proposed_date;

// -------- DATE -> "Thu, 17 Aug 2025" (ordem garantida)
const dateObj = new Date(reservation.date);

const formatDate = (date) => {
  const parts = new Intl.DateTimeFormat('en-GB', {
    weekday: 'short',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  }).formatToParts(date);

  const getPart = (type) => parts.find(p => p.type === type)?.value || '';

  return `${getPart('weekday')}, ${getPart('day')} ${getPart('month')} ${getPart('year')}`;
};

const formattedDate = formatDate(dateObj);

// -------- PROPOSED DATE -> "Thu, 17 Aug 2025"
const formattedProposedDate = proposedDateRaw
  ? formatDate(new Date(proposedDateRaw))
  : null;

// -------- TIME (reservation.time) -> "9:00 PM"
let timeObj;
if (typeof reservation.time === 'string' && /^\d{1,2}:\d{2}(:\d{2})?$/.test(reservation.time)) {
  const [h, m] = reservation.time.split(':');
  timeObj = new Date(2000, 0, 1, Number(h), Number(m));
} else {
  timeObj = new Date(reservation.time);
}

const formattedTime = new Intl.DateTimeFormat('en-US', {
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
}).format(timeObj);

// -------- PROPOSED TIME -> "9:00 PM"
let proposedTimeObj;
if (typeof proposedTimeRaw === 'string' && /^\d{1,2}:\d{2}(:\d{2})?$/.test(proposedTimeRaw)) {
  const [h, m] = proposedTimeRaw.split(':');
  proposedTimeObj = new Date(2000, 0, 1, Number(h), Number(m));
} else if (proposedTimeRaw) {
  proposedTimeObj = new Date(proposedTimeRaw);
}

const formattedProposedTime = proposedTimeObj
  ? new Intl.DateTimeFormat('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    }).format(proposedTimeObj)
  : null;

// -------- PEOPLE -> "1 guest" / "4 guests"
const people = Number(reservation.people);
const formattedPeople = `${people} ${people === 1 ? 'guest' : 'guests'}`;

// -------- DETAILS -> default "No details."
const formattedDetails =
  reservation.details && String(reservation.details).trim() !== ''
    ? String(reservation.details).trim()
    : 'No details.';

return [
  {
    json: {
      formattedDate,
      formattedProposedDate,
      formattedTime,
      formattedProposedTime,
      formattedPeople,
      formattedDetails,
    },
  },
];

